  host.querySelectorAll('[data-issue-catalog]').forEach(b=>b.onclick=()=>{host.querySelector('#tooling-catalogs').open=true;editCatalog(b.dataset.issueCatalog,b.dataset.id,!editing());});host.querySelectorAll('[data-catalog-view]').forEach(b=>b.onclick=()=>editCatalog(b.dataset.catalogView,b.dataset.id,true));host.querySelectorAll('[data-catalog-add]').forEach(b=>b.onclick=()=>editCatalog(b.dataset.catalogAdd));host.querySelectorAll('[data-catalog-edit]').forEach(b=>b.onclick=()=>editCatalog(b.dataset.catalogEdit,b.dataset.id));host.querySelectorAll('[data-catalog-delete]').forEach(b=>b.onclick=()=>remove(b.dataset.catalogDelete,b.dataset.id));
  window.VersionDraftUI.mount(host,{header:'.tooling-version',module:title(),scope:scope(),version:v,versions:control?.versions||[],active:active(),flow:f,historyClient:()=>client,actions:{begin:'#tooling-begin',save:'#tooling-save',submit:'#tooling-submit',withdraw:'#tooling-withdraw'},errors:error?'#tooling-errors details':null,missing:'#tooling-missing>details,#tooling-missing>.vd-unchecked',checked:{errors:!!control},failed:!!error,review:()=>showReview(f?.pendingId)});
