  area.querySelector('[data-iqc-disabled]').onchange=e=>{filter.disabled=e.target.checked;state.page=0;paint();};area.querySelector('[data-iqc-search]').oninput=e=>{filter.search=e.target.value;state.page=0;paint();};for(const [name,key]of [['category','categories'],['supplier','suppliers']])area.querySelector('[data-iqc-'+name+']').onchange=e=>{filter[key]=new Set([...e.target.selectedOptions].map(o=>o.value));state.page=0;paint();};area.querySelector('[data-iqc-add]').onclick=()=>{row.iqcIds=[...selection];onchange();area.replaceChildren();area.classList.remove('tooling-iqc-picker');};area.querySelector('[data-iqc-cancel]').onclick=()=>{area.replaceChildren();area.classList.remove('tooling-iqc-picker');};paint();
