 async function showIqcDetail(id){const d=makeDialog(t('Nguồn IQC đã duyệt','正式 IQC 來源'),`<p data-status>${h(t('Đang tải…','載入中…'))}</p><div data-iqc-detail-body></div>${button('data-close',t('Trở lại dụng cụ','返回器具'))}`);d.querySelector('[data-close]').onclick=()=>d.close();try{const response=await fetch('/api/tooling/iqc?partId='+encodeURIComponent(id),{cache:'no-store'}),result=await response.json();if(!response.ok)throw Error(result.error);if(!d.isConnected)return;d.querySelector('[data-status]').textContent=(result.sourceStatus==='removed'?t('Nguồn đã bị gỡ; nội dung lưu trữ','來源已移除；保留固定歷史'):result.sourceStatus==='disabled'?t('Đã ngưng sử dụng','已停用'):t('Dữ liệu đã duyệt','正式生效資料'))+' · '+result.versionId;window.IQCMasterUI.renderApprovedDetail(d.querySelector('[data-iqc-detail-body]'),result.snapshot,id,showPhoto);}catch(e){if(d.isConnected)d.querySelector('[data-status]').textContent=e.message;}}
 function reviewHTML(){return`<section class="tooling-page" data-i18n-skip="true"><h3>${h(title())}</h3><div data-tooling-review><p>${h(t('Đang tải hồ sơ…','正在載入案件…'))}</p></div></section>`;}
