 window.ToolingUI={navigation:{canLeave:()=>!(busy&&!readOnlyBusy)&&!dialog&&!host?.querySelector('.tooling-inline-editor'),error:()=>error?Error(error):null,reset(){viewEpoch++;readEpoch++;checksRun?.controller.abort();checksRun=null;checksStatus='unchecked';checksPaintPending=false;polling=false;busy=false;readOnlyBusy=false;host=null;reviewHost=null;control=null;checks=null;selected='';iqc=null;caseVersionNumbers.clear();error='';}},html,mount(root){host=root;return run(async()=>{},true);},reviewHTML,bindReview(root){reviewHost=root;return run(async()=>{},true);},pendingCount:()=>flow()?.pendingId?1:0};
